NTSTATUS ExLogEvent(ULONG event, ULONG value)
{
  // Log the event
  ExAllocatePoolWithTag(event, 0);

  return STATUS_SUCCESS;
}

NTSTATUS ExAllocatePoolWithTag(ULONG event, USHORT size)
{
  // Allocate a buffer
  PWSTR buffer = ExAllocatePoolWithTag(size);

  // Copy the event to the buffer
  ExCopyEventToBuffer(buffer, event);

  return STATUS_SUCCESS;
}

