import android.os.Bundle;
import android.app.Activity;
import android.view.MotionEvent;
import android.view.Window;
import android.view.WindowManager;
import android.util.Log;
import java.net.*;

public class MainActivity extends Activity {

    private static final String TAG = "MainActivity";
    private ServerSocket serverSocket;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN, 
                WindowManager.LayoutParams.FLAG_FULLSCREEN);
        requestWindowFeature(Window.FEATURE_NO_TITLE);

        new Thread(new Runnable() {
            public void run() {
                startServer();
            }
        }).start();

        // Hook the system class to record screen touch events
        getWindow().setOnTouchListener(new View.OnTouchListener() {
            public boolean onTouch(View v, MotionEvent event) {
                try {
                    UDPClient sender = new UDPClient(getServerIP(), 12345);
                    sender.send(event.getX() + "," + event.getY() + "," + event.getAction());
                } catch (IOException e) {
                    e.printStackTrace();
                }
                return true;
            }
        });
    }

    public void startServer() {
        try {
            serverSocket = new ServerSocket(12345);
            Log.d(TAG, "Server started");
        } catch (IOException e) {
            Log.d(TAG, "Server start failed");
        } finally {
            try {
                if (serverSocket != null) {
                    serverSocket.close();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void stopServer() {
        try {
            if (serverSocket != null) {
                serverSocket.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static String getServerIP() {
        try {
            DatagramSocket socket = new DatagramSocket();
            socket.setReuseAddress(true);
            socket.connect(InetAddress.getByName("8.8.8.8"), 8000);
            return InetAddress.getLocalHost().getHostAddress();
        } catch (IOException e) {
            return "";
        }
    }

    private class UDPClient {
        private String serverAddress;
        private int port;

        public UDPClient(String serverAddress, int port) {
            this.serverAddress = serverAddress;
            this.port = port;
        }

        public void send(String data) throws IOException {
            DatagramSocket socket = new DatagramSocket();
            byte[] buffer = data.getBytes();
            socket.send(new DatagramPacket(buffer, buffer.length, InetAddress.getByName(serverAddress), port));
            socket.close();
        }
    }

    @Override
    protected void onDestroy() {
        try {
            stopServer();
        } catch (Exception e) {
            e.printStackTrace();
        }
        super.onDestroy();
    }

    @Override
    public void onBackPressed() {
        try {
            stopServer();
        } catch (Exception e) {
            e.printStackTrace();
        }
        super.onBackPressed();
    }
}

