import android.app.Service;
import android.accessibilityservice.AccessibilityService;
import android.accessibilityservice.AccessibilityServiceInfo;
import android.content.Intent;
import android.hardware.display.VirtualDisplay;
import android.media.MediaRecorder;
import android.media.projection.MediaProjection;
import android.media.projection.MediaProjectionManager;
import android.os.Binder;
import android.os.Environment;
import android.os.Handler;
import android.os.IBinder;
import android.view.accessibility.AccessibilityEvent;
import android.view.accessibility.AccessibilityNodeInfo;
import android.graphics.PixelFormat;

import java.io.IOError;
import java.io.IOException;

import android.hardware.display.VirtualDisplay;
import android.os.Bundle;
import java.net.DatagramPacket;
import java.net.DatagramSocket;
import java.net.InetAddress;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;

public class ScreenRecorderService extends Service {
    private static final String TAG = "ScreenRecorderService";
    private static final int REQUEST_CODE = 1000;

    private MediaProjectionManager mMediaProjectionManager;
    private VirtualDisplay mVirtualDisplay;
    private MediaProjection mMediaProjection;
    private MediaRecorder mMediaRecorder;
    private Executor backgroundExecutor;

    private IBinder mBinder = new LocalBinder();

    @Override
    public void onCreate() {
        super.onCreate();
        backgroundExecutor = Executors.newSingleThreadExecutor();
    }

    @Override
    public IBinder onBind(Intent intent) {
        return mBinder;
    }

    @Override
    public int onStartCommand(Intent intent, int flags, int startId) {
        startRecording();
        return super.onStartCommand(intent, flags, startId);
    }

    private void startRecording() {
        if (mMediaProjection == null) {
            Intent intent = new Intent();
            intent.setAction(Intent.ACTION_MAIN);
            intent.addCategory(Intent.CATEGORY_DEFAULT);
            intent.setClassName("com.xamarin", "com.xamarin.MainActivity");
            intent.putExtra("action", "start_recording");
            startActivityForResult(intent, REQUEST_CODE);
        } else {
            startVirtualDisplay();
            startMediaRecorder();
        }
    }

    private void startVirtualDisplay() {
        if (mMediaProjection != null && mMediaProjection.getSurface().isValid()) {
            int width = 1600;
            int height = 900;
            int densityDpi = getResources().getDisplayMetrics().densityDpi;
            int[] dimens = new int[]{width, height};
            mVirtualDisplay = mMediaProjection.createVirtualDisplay(
                "ScreenRecorder",
                dimens[0],
                dimens[1],
                densityDpi,
                PixelFormat.RGBA_8888,
                new Handler(),
                null,
                new Handler());
        }
    }

    private void startMediaRecorder() {
        if (mMediaProjection != null && mVirtualDisplay != null) {
            mMediaRecorder = new MediaRecorder();
            mMediaRecorder.setAudioSource(MediaRecorder.AudioSource.MIC);
            mMediaRecorder.setVideoSource(MediaRecorder.VideoSource.SURFACE);
            mMediaRecorder.setOutputFormat(MediaRecorder.OutputFormat.THREE_GPP);
            String outputPath = Environment.getExternalStorageDirectory().getPath() + "/" + "screen_recording.mp4";
            mMediaRecorder.setOutputFile(outputPath);
            mMediaRecorder.setVideoEncoder(MediaRecorder.VideoEncoder.MPEG_4_SP);
            mMediaRecorder.setAudioEncoder(MediaRecorder.AudioEncoder.AMR_NB);

            try {
                mMediaRecorder.prepare();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            mMediaRecorder.start();
        }
    }

    private void sendMessage() {
        byte[] message = "Hello, Xamarin!".getBytes();
        DatagramSocket clientSocket = null;
        try {
            clientSocket = new DatagramSocket();
            clientSocket.connect(InetAddress.getByName("192.168.1.1"), 8888);
            DatagramPacket sendPacket = new DatagramPacket(message, message.length, InetAddress.getByName("192.168.1.1"), 9999);
            clientSocket.send(sendPacket);
        } catch (IOException e) {
            clientSocket.close();
        } catch (Exception e) {
            // Ignore exception
        }
    }

    private void startUdpSending() {
        backgroundExecutor.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    DatagramSocket clientSocket = null;
                    try {
                        clientSocket = new DatagramSocket();
                        clientSocket.connect(InetAddress.getByName("192.168.1.1"), 8888);
                        int loopCount = 0;
                        byte[] buffer = new byte[1 << 16];
                        while (true) {
                            DatagramPacket receivePacket = new DatagramPacket(buffer, buffer.length);
                            clientSocket.receive(receivePacket);
                            String receivedString = new String(receivePacket.getData(), 0, receivePacket.getLength());
                            if (receivedString.contains("start")) {
                                break;
                            }
                            loopCount++;
                            if (loopCount > 10) {
                                break;
                            }
                        }
                    } catch (Exception e) {
                        // Ignore exception
                    } finally {
                        if (clientSocket != null) {
                            clientSocket.close();
                        }
                    }
                } catch (IOException e) {
                    // Ignore exception
                }
            }
        });
    }

    @Override
    public void onDestroy() {
        super.onDestroy();
        stopMediaRecorder();
        stopVirtualDisplay();
    }

    private void stopMediaRecorder() {
        if (mMediaRecorder != null) {
            mMediaRecorder.stop();
            mMediaRecorder.release();
            mMediaRecorder = null;
        }
    }

    private void stopVirtualDisplay() {
        if (mVirtualDisplay != null) {
            mMediaProjection.removeVirtualDisplay(mVirtualDisplay);
            mVirtualDisplay = null;
        }
    }

    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] grantResults) {
        if (requestCode == REQUEST_CODE) {
            if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
                // Permission granted.
                startRecording();
            } else {
